use uasf_queue::model::{Queue,Ticket};
fn ticket(id:u64,source:&str,ready:bool)->Ticket{Ticket{id,source:source.into(),deadline:100,ready}}
#[test]fn slots_are_not_reused_on_cancellation_without_reap(){let mut q=Queue::default();for id in 0..3{q.submit(ticket(id,"a",true)).unwrap();}assert_eq!(q.dispatch(0).unwrap().id,0);assert_eq!(q.dispatch(0).unwrap().id,1);q.cancel_waiting(0);assert!(q.dispatch(0).is_none());q.reaped(0);assert_eq!(q.dispatch(0).unwrap().id,2);}
#[test]fn ready_fifo_and_round_robin_survive_source_flood(){let mut q=Queue::default();for id in 0..16{q.submit(ticket(id,"a",true)).unwrap();}q.submit(ticket(50,"b",true)).unwrap();assert_eq!(q.dispatch(0).unwrap().id,0);assert_eq!(q.dispatch(0).unwrap().id,50);q.reaped(0);assert_eq!(q.dispatch(0).unwrap().id,1);}
#[test]fn unready_head_does_not_block_ready_same_or_other_source(){let mut q=Queue::default();q.submit(ticket(0,"a",false)).unwrap();q.submit(ticket(1,"a",true)).unwrap();q.submit(ticket(2,"b",true)).unwrap();assert_eq!(q.dispatch(0).unwrap().id,1);assert_eq!(q.dispatch(0).unwrap().id,2);q.reaped(1);assert!(q.dispatch(0).is_none());q.ready(0,true);assert_eq!(q.dispatch(0).unwrap().id,0);}
#[test]fn finite_total_and_source_limits_include_unready(){let mut q=Queue::default();for id in 0..16{q.submit(ticket(id,"a",false)).unwrap();}assert_eq!(q.submit(ticket(16,"a",true)),Err("query_source_queue_full"));for id in 16..32{q.submit(ticket(id,"b",false)).unwrap();}assert_eq!(q.submit(ticket(32,"c",true)),Err("query_queue_full"));}
#[test]fn expiry_and_duplicate_do_not_execute(){let mut q=Queue::default();q.submit(ticket(1,"a",true)).unwrap();assert_eq!(q.submit(ticket(1,"b",true)),Err("query_duplicate_request"));assert_eq!(q.expired(100),vec![1]);assert!(q.dispatch(100).is_none());q.cancel_waiting(1);assert_eq!(q.len(),0);}
#[test]fn readiness_changes_do_not_extend_deadline(){let mut q=Queue::default();q.submit(ticket(0,"a",false)).unwrap();q.ready(0,true);assert!(q.dispatch(101).is_none());}
